from decimal import Decimal, InvalidOperation
import math
import pandas as pd

doc_id = "97458f1a947089d9fe6dcb65d90a87fe"
records = documents[doc_id]
if isinstance(records, dict):
    records = records.get("records", records.get("rows", []))

def is_blank(value):
    if value is None:
        return True
    if isinstance(value, float) and math.isnan(value):
        return True
    return isinstance(value, str) and value.strip() == ""

if not records:
    result = pd.DataFrame([{
        "status": "failed",
        "reason": "no_data_rows",
        "total_amount": None,
        "average_amount": None,
        "record_count": None,
        "max_amount": None
    }])
else:
    first_record = records[0]
    if not isinstance(first_record, dict) or "amount" not in first_record:
        result = pd.DataFrame([{
            "status": "failed",
            "reason": "missing_amount_field",
            "total_amount": None,
            "average_amount": None,
            "record_count": None,
            "max_amount": None
        }])
    else:
        amounts = []
        invalid_rows = []
        data_row_count = 0
        for record_index, record in enumerate(records):
            values = list(record.values()) if isinstance(record, dict) else [record]
            if all(is_blank(value) for value in values):
                continue
            data_row_count += 1
            raw_amount = record.get("amount") if isinstance(record, dict) else None
            if is_blank(raw_amount):
                invalid_rows.append({
                    "row_position": record_index + 2,
                    "reason": "empty_amount"
                })
                continue
            try:
                parsed_amount = Decimal(str(raw_amount).strip())
                if not parsed_amount.is_finite():
                    raise InvalidOperation
            except (InvalidOperation, ValueError):
                invalid_rows.append({
                    "row_position": record_index + 2,
                    "reason": "invalid_amount"
                })
                continue
            amounts.append(parsed_amount)

        if invalid_rows:
            result = pd.DataFrame([{
                "status": "failed",
                "reason": f"{len(invalid_rows)}_invalid_rows",
                "first_invalid_row": invalid_rows[0]["row_position"],
                "first_invalid_reason": invalid_rows[0]["reason"],
                "total_amount": None,
                "average_amount": None,
                "record_count": None,
                "max_amount": None
            }])
        elif data_row_count == 0:
            result = pd.DataFrame([{
                "status": "failed",
                "reason": "no_data_rows",
                "total_amount": None,
                "average_amount": None,
                "record_count": None,
                "max_amount": None
            }])
        else:
            total_amount = sum(amounts, Decimal("0"))
            average_amount = total_amount / Decimal(data_row_count)
            max_amount = max(amounts)
            result = pd.DataFrame([{
                "status": "success",
                "reason": None,
                "total_amount": total_amount,
                "average_amount": average_amount,
                "record_count": data_row_count,
                "max_amount": max_amount
            }])

result = result.reset_index(drop=True)

